<?php get_header();while(have_posts()):the_post();$profile=badaround_blog_profile(get_the_ID()); ?>
<main id="main-content" class="ba-blog ba-blog-single ba-blog-tone--<?php echo esc_attr($profile['slug']); ?>"><article>
<header class="ba-blog-article-header ba-container"><nav class="ba-blog-breadcrumbs" aria-label="Percorso"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><span aria-hidden="true">/</span><a href="<?php echo esc_url(home_url('/blog/')); ?>">Blog</a><?php if($profile['term']): ?><span aria-hidden="true">/</span><a href="<?php echo esc_url(get_category_link($profile['term']->term_id)); ?>"><?php echo esc_html($profile['name']); ?></a><?php endif; ?></nav>
<span class="ba-blog-category"><?php echo badaround_pin_svg($profile['pin']); ?><span><?php echo esc_html($profile['name']); ?></span></span><h1><?php the_title(); ?></h1><?php if(has_excerpt()): ?><p class="ba-blog-lead"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><p class="ba-blog-byline">Redazione BadAround · <time datetime="<?php echo esc_attr(get_the_date(DATE_W3C)); ?>"><?php echo esc_html(get_the_date('j F Y')); ?></time><?php if(get_the_modified_date('Y-m-d')!==get_the_date('Y-m-d')): ?> · Aggiornato il <?php echo esc_html(get_the_modified_date('j F Y'));endif; ?></p></header>
<div class="ba-blog-article-cover ba-container"><?php if(has_post_thumbnail()):the_post_thumbnail('ba-detail',array('loading'=>'eager','fetchpriority'=>'high'));else: ?><img src="<?php echo esc_url(badaround_blog_cover(get_the_ID())); ?>" alt="<?php echo esc_attr($profile['name'].' — BadAround'); ?>" width="1200" height="630" decoding="async"><?php endif; ?></div>
<div class="ba-blog-prose"><?php the_content();wp_link_pages(); ?></div>
<footer class="ba-blog-article-footer"><h2>Le informazioni utili iniziano dalle persone</h2><p>Hai qualcosa da segnalare nella tua zona? Descrivi i fatti e aiutaci a informare la community.</p><a class="ba-button ba-button--urgent" href="<?php echo esc_url(home_url('/segnala-un-evento/')); ?>">Segnala un evento</a><a class="ba-blog-back" href="<?php echo esc_url(home_url('/blog/')); ?>">← Torna al blog</a></footer></article>
</main><?php endwhile;get_footer(); ?>
